                extractCompanyCode()); // This will be set before calculate is called
        return priceCalculator.nightlyPrice(room, checkIn, checkOut, discount);
    }

    @Override
    public BigDecimal calculateRefund(BigDecimal amountPaid) {
        return amountPaid;
    }

    private String extractCompanyCode() {
        // This is a placeholder; the actual implementation will need the company code passed
        return null;
    }
}

